import math


class Shape:
    def area(self):
        return 0


class Rect(Shape):
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h


class Circle(Shape):
    def __init__(self, r):
        self.r = r

    def area(self):
        return round(math.pi * self.r ** 2, 2)


def total_area(shapes):
    return round(sum(s.area() for s in shapes), 2)

